def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the uniform divider that splits the grid into equal-sized panels.
    divider = None
    for r in range(h):
        if all(x == grid[r][0] for x in grid[r]) and r == h - r - 1:
            divider = ("h", r)
            break
    if divider is None:
        for c in range(w):
            if all(grid[r][c] == grid[0][c] for r in range(h)) and c == w - c - 1:
                divider = ("v", c)
                break

    if divider is None:
        return [row[:] for row in grid]

    if divider[0] == "h":
        k = divider[1]
        a, b = grid[:k], grid[k + 1:]
    else:
        k = divider[1]
        a = [row[:k] for row in grid]
        b = [row[k + 1:] for row in grid]

    common = set(x for row in a for x in row) & set(x for row in b for x in row)
    base = next(iter(common)) if common else 0

    return [[3 if a[r][c] == b[r][c] else base
             for c in range(len(a[0]))]
            for r in range(len(a))]
